set -eu
sudo mysql --batch --skip-column-names <<'ANTRIEB_SQL'
CREATE DATABASE IF NOT EXISTS galera_benchmark;
CREATE TABLE IF NOT EXISTS galera_benchmark.replication_proof (
  id INT NOT NULL PRIMARY KEY,
  writer VARCHAR(32) NOT NULL,
  phase VARCHAR(64) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO galera_benchmark.replication_proof (id,writer,phase) VALUES (101,'node1','three-member-baseline')
  ON DUPLICATE KEY UPDATE writer=VALUES(writer),phase=VALUES(phase);
SELECT id,writer,phase FROM galera_benchmark.replication_proof ORDER BY id;
SHOW GLOBAL STATUS LIKE 'wsrep_last_committed';
ANTRIEB_SQL

